import sys
fn guardedAnd(guard: bool, divisor: i64) -> bool {
  return guard && (1 / divisor > 0)
}
fn guardedOr(guard: bool, divisor: i64) -> bool {
  return guard || (1 / divisor > 0)
}
fn answer() -> i64 {
  var opened = sys.Pipe.open()
  if (opened == null) { return 0 }
  var ready = opened!
  var live = move ready
  var readHandle = live.readEnd()
  var writeHandle = live.writeEnd()
  var readClosed = live.closeRead()
  var closedReadHandle = live.readEnd()
  var writeClosed = live.closeWrite()
  var closedWriteHandle = live.writeEnd()
  var closed = (move live).close()
  if (guardedAnd(false, 0)) { return 0 }
  if (!guardedOr(true, 0)) { return 0 }
  var handlesValid = readHandle >= 0 && writeHandle >= 0
  if (!handlesValid || closedReadHandle != -1 || closedWriteHandle != -1) { return 0 }
  if (!readClosed || !writeClosed || !closed) { return 0 }
  return 1
}

pipe_close_failure.text:
import sys
enum CleanupFailure { Negative { code: i64 } }
fn fail(value: i64) -> i64 {
  if (value < 0) { throw CleanupFailure.Negative { code: value } }
  return value
}
fn doomed() -> i64 {
  var live = sys.Pipe(2147483646, 2147483647)
  defer {
    live.closeRead()
    live.closeWrite()
  }
  return fail(-2)
}
fn answer() -> i64 {
  try { return doomed() } catch (error) { return 1 }
}

