original_Pipe_declaration.text:
export class Pipe {
    _readHandle: i64
    _writeHandle: i64

    constructor(readHandle: i64, writeHandle: i64) {
        this._readHandle = readHandle
        this._writeHandle = writeHandle
    }

    readEnd() -> i64 { return this._readHandle }

    writeEnd() -> i64 { return this._writeHandle }

    read(maxBytes: i64 = 8192) -> Array<u8>? {
        if (this._readHandle < 0 || maxBytes < 0) { return null }
        return __pipeRead(this._readHandle, maxBytes)
    }

    write(data: Array<u8>) -> i64 {
        if (this._writeHandle < 0) { return -1 }
        return __pipeWrite(this._writeHandle, data)
    }

    ref closeRead() -> bool {
        if (this._readHandle < 0) { return true }
        var ok = __pipeClose(this._readHandle)
        this._readHandle = -1
        return ok
    }

    ref closeWrite() -> bool {
        if (this._writeHandle < 0) { return true }
        var ok = __pipeClose(this._writeHandle)
        this._writeHandle = -1
        return ok
    }

    move close() -> bool {
        var r = true
        if (this._readHandle >= 0) { r = __pipeClose(this._readHandle) }
        var w = true
        if (this._writeHandle >= 0) { w = __pipeClose(this._writeHandle) }
        if (r) { return w }
        return false
    }

    static open() -> Pipe? {
        var ends = __pipeOpen()
        if (ends == null) { return null }
        return Pipe(ends!.0, ends!.1)
    }
}
